// Per-stage data descriptor (table generated by tools/gen_assets.py into stage_defs.c, ROM0).
#ifndef STAGE_DEF_H
#define STAGE_DEF_H
#include <stdint.h>

#define N_STAGES 4            // scrolling stages (stage_defs)
#define N_MISSIONS 6          // missions on the map: the four stages, the gun-cam mission and the escape run
#define FLAT_SID 4            // mission index of Flatwoods Drift (gun cam)
#define ESC_SID 5             // mission index of Escape Run
#define ROWS_PER_BANK 409

typedef struct {
    uint8_t dbank;                 // bank holding tiles, sprites, palettes and boss data
    const uint8_t *scen0; uint8_t n_scen0;    // BG bank 0 ids N_COMMON..
    const uint8_t *scen1; uint8_t n_scen1;    // BG bank 1 ids 0..
    const uint8_t *spr;   uint8_t n_spr;      // OBJ VRAM bank 1 tiles 0..
    const uint16_t *objpal;                   // 4 palettes -> OBJ 3..6
    const uint8_t *initbp;                    // 8 BG palette library indices
    uint8_t nchunks;
    uint8_t rbank[3];
    const uint8_t *rptr[3];
    uint16_t n_rows;
    uint16_t cp[3];
    const uint8_t *btiles; uint8_t n_btiles;
    const uint8_t *bswap;  uint8_t n_swap;
    const uint8_t *bvar;
    uint8_t hit_bp, boss_bp6;
    uint8_t mus_stage, mus_boss;
    uint8_t logic_bank;
} StageDef;

extern const StageDef stage_defs[N_STAGES];
extern const char * const stage_names[N_STAGES];
#endif
